    "Web Scraping at Scale": [
      { title: 'Async Web Crawler', description: 'High-performance async crawler with rate limiting and concurrent requests.', code: "import asyncio\nimport aiohttp\nfrom bs4 import BeautifulSoup\nfrom urllib.parse import urljoin, urlparse\n\nclass AsyncCrawler:\n    def __init__(self, max_concurrent=10, delay=1.0):\n        self.semaphore = asyncio.Semaphore(max_concurrent)\n        self.delay = delay\n        self.visited = set()\n        self.results = []\n    \n    async def fetch(self, session, url):\n        async with self.semaphore:\n            try:\n                await asyncio.sleep(self.delay)  # Rate limiting\n                async with session.get(url, timeout=aiohttp.ClientTimeout(total=10)) as resp:\n                    if resp.status == 200:\n                        html = await resp.text()\n                        return url, html\n            except Exception as e:\n                print(f\"Error fetching {url}: {e}\")\n        return url, None\n    \n    def parse_links(self, html, base_url):\n        soup = BeautifulSoup(html, \"html.parser\")\n        links = set()\n        for a in soup.find_all(\"a\", href=True):\n            link = urljoin(base_url, a[\"href\"])\n            if urlparse(link).netloc == urlparse(base_url).netloc:\n                links.add(link)\n        return links\n    \n    async def crawl(self, start_url, max_pages=100):\n        async with aiohttp.ClientSession() as session:\n            queue = [start_url]\n            tasks = []\n            \n            while queue and len(self.visited) < max_pages:\n                url = queue.pop(0)\n                if url in self.visited:\n                    continue\n                self.visited.add(url)\n                \n                task = asyncio.create_task(self.fetch(session, url))\n                tasks.append(task)\n                \n                if len(tasks) >= 20:\n                    results = await asyncio.gather(*tasks)\n                    for url, html in results:\n                        if html:\n                            links = self.parse_links(html, url)\n                            queue.extend(links - self.visited)\n                    tasks = []\n            \n            if tasks:\n                await asyncio.gather(*tasks)\n            \n            print(f\"Crawled {len(self.visited)} pages\")\n            return self.results\n\n# crawler = AsyncCrawler(max_concurrent=5, delay=0.5)\n# asyncio.run(crawler.crawl(\"https://example.com\"))" },
    ],
    "API Fan-out": [
      { title: 'Parallel API Client', description: 'Make parallel API calls with timeout, retry, and error handling.', code: "import asyncio\nimport aiohttp\nfrom typing import List, Dict, Any\nimport time\n\nasync def fetch_with_retry(session, url, max_retries=3, timeout=10):\n    \"\"\"Fetch URL with retry logic.\"\"\"\n    for attempt in range(max_retries):\n        try:\n            async with session.get(url, timeout=aiohttp.ClientTimeout(total=timeout)) as resp:\n                if resp.status == 200:\n                    return await resp.json()\n                elif resp.status == 429:  # Rate limited\n                    wait = 2 ** attempt\n                    await asyncio.sleep(wait)\n                else:\n                    return {\"error\": f\"HTTP {resp.status}\", \"url\": url}\n        except asyncio.TimeoutError:\n            if attempt == max_retries - 1:\n                return {\"error\": \"Timeout\", \"url\": url}\n        except Exception as e:\n            if attempt == max_retries - 1:\n                return {\"error\": str(e), \"url\": url}\n    return {\"error\": \"Max retries exceeded\", \"url\": url}\n\nasync def fetch_all(urls: List[str]) -> List[Dict[str, Any]]:\n    \"\"\"Fetch multiple URLs in parallel.\"\"\"\n    async with aiohttp.ClientSession() as session:\n        tasks = [fetch_with_retry(session, url) for url in urls]\n        return await asyncio.gather(*tasks)\n\n# Usage\nstart = time.time()\nurls = [f\"https://httpbin.org/get?id={i}\" for i in range(20)]\nresults = asyncio.run(fetch_all(urls))\nelapsed = time.time() - start\n\nsuccess = sum(1 for r in results if \"error\" not in r)\nprint(f\"Fetched {success}/{len(urls)} URLs in {elapsed:.2f}s\")" },
    ],
    "ML Data Prep": [
      { title: 'Parallel Data Processing', description: 'Process large datasets in parallel using ProcessPoolExecutor.', code: "from concurrent.futures import ProcessPoolExecutor, as_completed\nimport multiprocessing\nimport time\nimport math\n\ndef process_chunk(chunk_id: int, data: list) -> dict:\n    \"\"\"Process a chunk of data (runs in separate process).\"\"\"\n    results = []\n    for item in data:\n        # Simulate heavy computation\n        result = sum(math.sqrt(i) for i in range(item))\n        results.append(result)\n    \n    return {\n        \"chunk_id\": chunk_id,\n        \"count\": len(data),\n        \"sum\": sum(results),\n        \"mean\": sum(results) / len(results) if results else 0,\n    }\n\ndef parallel_process(data: list, num_workers: int = None) -> list:\n    \"\"\"Split data into chunks and process in parallel.\"\"\"\n    if num_workers is None:\n        num_workers = multiprocessing.cpu_count()\n    \n    chunk_size = max(1, len(data) // num_workers)\n    chunks = [data[i:i+chunk_size] for i in range(0, len(data), chunk_size)]\n    \n    results = []\n    with ProcessPoolExecutor(max_workers=num_workers) as executor:\n        futures = {executor.submit(process_chunk, i, chunk): i \n                   for i, chunk in enumerate(chunks)}\n        \n        for future in as_completed(futures):\n            result = future.result()\n            results.append(result)\n            print(f\"Chunk {result['chunk_id']}: {result['count']} items\")\n    \n    return results\n\n# Generate test data\ndata = [1000 + i * 100 for i in range(20)]\nstart = time.time()\nresults = parallel_process(data, num_workers=4)\nelapsed = time.time() - start\n\ntotal_sum = sum(r[\"sum\"] for r in results)\nprint(f\"Processed {len(data)} items in {elapsed:.2f}s\")" },
    ],
