    "AI & Machine Learning": [
      { title: 'RAG Pipeline with Vector Search', description: 'Build a Retrieval-Augmented Generation system for Q&A.', code: "import numpy as np\nfrom typing import List, Dict\n\nclass SimpleRAG:\n    \"\"\"Minimal RAG implementation with vector search.\"\"\"\n    def __init__(self):\n        self.documents: List[Dict] = []\n        self.embeddings: np.ndarray = None\n    \n    def add_documents(self, docs: List[str], metadatas: List[dict] = None):\n        \"\"\"Add documents with TF-IDF embeddings.\"\"\"\n        for i, doc in enumerate(docs):\n            meta = metadatas[i] if metadatas else {\"source\": f\"doc_{i}\"}\n            self.documents.append({\"text\": doc, \"metadata\": meta})\n        \n        # Simple TF-IDF embedding\n        vocab = set()\n        for doc in docs:\n            vocab.update(doc.lower().split())\n        vocab = sorted(vocab)\n        \n        embeddings = np.zeros((len(docs), len(vocab)))\n        for i, doc in enumerate(docs):\n            words = doc.lower().split()\n            for word in words:\n                if word in vocab:\n                    embeddings[i, vocab.index(word)] += 1\n        \n        # Normalize\n        norms = np.linalg.norm(embeddings, axis=1, keepdims=True)\n        self.embeddings = embeddings / (norms + 1e-8)\n    \n    def query(self, question: str, k: int = 3) -> List[Dict]:\n        \"\"\"Find most relevant documents.\"\"\"\n        # Embed query\n        vocab_size = self.embeddings.shape[1]\n        query_vec = np.zeros(vocab_size)\n        words = question.lower().split()\n        \n        # Need to build vocab from documents\n        all_words = set()\n        for doc in self.documents:\n            all_words.update(doc[\"text\"].lower().split())\n        vocab = sorted(all_words)\n        \n        for word in words:\n            if word in vocab:\n                query_vec[vocab.index(word)] += 1\n        \n        query_vec = query_vec / (np.linalg.norm(query_vec) + 1e-8)\n        \n        # Cosine similarity\n        similarities = self.embeddings @ query_vec\n        top_k = np.argsort(similarities)[-k:][::-1]\n        \n        return [\n            {\"text\": self.documents[i][\"text\"], \n             \"score\": float(similarities[i]),\n             \"metadata\": self.documents[i][\"metadata\"]}\n            for i in top_k\n        ]\n\n# Usage\nrag = SimpleRAG()\nrag.add_documents([\n    \"Python is great for data science and machine learning.\",\n    \"Django is a high-level web framework for building APIs.\",\n    \"NumPy provides fast array operations for numerical computing.\",\n    \"Pandas is essential for data manipulation and analysis.\",\n    \"Flask is a lightweight micro-framework for web applications.\",\n])\n\nresults = rag.query(\"What is best for data analysis?\", k=3)\nfor r in results:\n    print(f\"Score: {r['score']:.3f} | {r['text'][:80]}...\")" },
    ],
